<div class="{{ $classes }}" id="{{ $id }}" data-cm-controller="data-table" data-cm-data-table-sort-key="{{ $sort['key'] ?? '' }}" data-cm-data-table-sort-direction="{{ $sort['direction'] ?? '' }}" data-cm-data-table-page="{{ $page }}" data-cm-data-table-page-count="{{ $pageCount }}" data-cm-data-table-page-size="{{ $pageSize }}"@if ($totalRows !== null) data-cm-data-table-total-rows="{{ $totalRows }}"@endif data-cm-data-table-selected-count="{{ count($selected) }}"{!! $attributes !!}><div class="cm-data-table__scroll"><table class="cm-data-table__table">@if ($caption !== '')<caption class="cm-data-table__caption">{{ $caption }}</caption>@endif<thead class="cm-data-table__head"><tr>@if ($selectable)<th class="cm-data-table__selection" scope="col"><input type="checkbox" aria-label="{{ $selectAllLabel }}" data-cm-data-table-select-all@if ($rows !== [] && count($selected) === count($rows)) checked@endif></th>@endif@foreach ($columns as $column)<th scope="col"@if ($column['align'] !== 'start') class="cm-data-table__cell--{{ $column['align'] }}"@endif@if ($column['sortable']) aria-sort="{{ $sort !== null && $sort['key'] === $column['key'] ? $sort['direction'] : 'none' }}"@endif>@if ($column['sortable'])<button class="cm-data-table__sort" type="button" aria-label="{{ $sort === null || $sort['key'] !== $column['key'] ? 'Sort ' . $column['header'] . ' ascending' : ($sort['direction'] === 'ascending' ? 'Sort ' . $column['header'] . ' descending' : 'Clear sorting for ' . $column['header']) }}" data-cm-data-table-sort="{{ $column['key'] }}">{{ $column['header'] }}<span class="cm-data-table__sort-indicator" aria-hidden="true"></span></button>@else{{ $column['header'] }}@endif</th>@endforeach</tr></thead><tbody class="cm-data-table__body">@if ($stateText !== null)<tr><td class="cm-data-table__state" colspan="{{ $columnCount }}" role="status">{{ $stateText }}</td></tr>@else@foreach ($rows as $row)<tr data-cm-data-table-row="{{ $row['id'] }}"@if ($row['selected']) class="cm-data-ta